import json
for a,b in [('lab/input-final-raw.json','lab/input-final.json'),('lab/model-final-raw.json','lab/model-final.json')]:
    A=json.load(open(a)); B=json.load(open(b))
    print('=====',a,'vs',b)
    def walk(x,y,p=''):
        if type(x)!=type(y): print('TYPE',p,type(x),type(y)); return
        if isinstance(x,dict):
            for k in sorted(set(x)|set(y)):
                if k not in x: print('ONLY-B',p+'/'+k,y[k] if not isinstance(y[k],(dict,list)) else '...')
                elif k not in y: print('ONLY-A',p+'/'+k,x[k] if not isinstance(x[k],(dict,list)) else '...')
                else: walk(x[k],y[k],p+'/'+k)
        elif isinstance(x,list):
            if len(x)!=len(y): print('LEN',p,len(x),len(y))
            for i,(u,v) in enumerate(zip(x,y)): walk(u,v,p+f'[{i}]')
        else:
            if x!=y: print('DIFF',p,x,'->',y)
    walk(A,B)
